import { useInfiniteQuery } from '@tanstack/react-query';

interface PageResult {
  items: Item[];
  nextCursor: string | null;
}

async function fetchItems({ pageParam }: { pageParam: string }): Promise<PageResult> {
  const url = pageParam
    ? `/api/items?cursor=${encodeURIComponent(pageParam)}`
    : '/api/items';
  const res = await fetch(url);
  return res.json();
}

function InfiniteItemList() {
  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    isLoading,
    isError,
    error,
  } = useInfiniteQuery({
    queryKey: ['items', 'infinite'],
    queryFn: fetchItems,
    initialPageParam: '',        // First request has no cursor
    getNextPageParam: (lastPage) => lastPage.nextCursor,
    // Returns nextCursor if more pages exist, undefined if done
  });

  if (isLoading) return <p>Loading items...</p>;
  if (isError)   return <p>Error: {error.message}</p>;

  // Flatten all pages into a single list for rendering
  const allItems = data.pages.flatMap((page) => page.items);

  return (
    <div>
      <ul>
        {allItems.map((item) => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>

      <button
        onClick={() => fetchNextPage()}
        disabled={!hasNextPage || isFetchingNextPage}
      >
        {isFetchingNextPage ? 'Loading more...' : 'Load More'}
      </button>

      {!hasNextPage && <p className="end-marker">You've reached the end.</p>}
    </div>
  );
}

